import { FormEvent, forwardRef, useContext, useEffect, useId, useState } from 'react';
import { TextAreaElementClass, TextAreaElementClassProps, TextAreaProps } from './type';
import { ElementClassManager, ParadiseUIContext } from '@paradise-ui/common';
import { defaultTextAreaElementClass, tailwindTextAreaElementClass } from './elementClass';
import clsx from 'clsx';

export const TextArea = forwardRef<
	HTMLTextAreaElement,
	TextAreaProps & ElementClassManager<TextAreaElementClassProps, TextAreaElementClass>
>((props, ref) => {
	const {
		label = '',
		secondaryLabel = '',
		variant = 'outlined',
		size = 'md',
		autoResize = false,
		name = '',
		className = '',
		placeholder = '',
		value,
		invalid = false,
		disabled = false,
		errorMessage = '',
		helperText = '',
		onChange,
		elementClass,
		extraElementClass,
		...rest
	} = props;

	const puiContext = useContext(ParadiseUIContext);
	const [focus, setFocus] = useState<boolean>(false);
	const elementClassProps = { variant, size, invalid, disabled, ...props, focus };
	const [TextAreaElementClass, setTextAreaElementClass] = useState<TextAreaElementClass>(defaultTextAreaElementClass(elementClassProps));

	useEffect(() => {
		let newElementClass = defaultTextAreaElementClass(elementClassProps);
		if (puiContext) {
			if (puiContext.elementClassLibrary === 'tailwind') {
				newElementClass = tailwindTextAreaElementClass(elementClassProps);
			}

			newElementClass = {
				...newElementClass,
				...((puiContext.componentElementClasses?.textArea && puiContext.componentElementClasses?.textArea(elementClassProps)) || {})
			};
		}
		if (elementClass) {
			newElementClass = { ...newElementClass, ...elementClass(elementClassProps) };
		}
		setTextAreaElementClass(newElementClass);
	}, [props, focus]);

	const resize = (e: FormEvent<HTMLTextAreaElement>) => {
		if (autoResize) {
			e.currentTarget.style.height = 'auto';
			e.currentTarget.style.height = e.currentTarget.scrollHeight + 'px';
		}
	};

	const id = useId();
	const inputId = `${id}-${name}`;
	const descriptionId = `${id}-description`;

	return (
		<div className={clsx(TextAreaElementClass.root, extraElementClass?.root)} aria-disabled={disabled}>
			<div className={clsx(TextAreaElementClass.labelBlock, extraElementClass?.labelBlock)}>
				<label className={clsx(TextAreaElementClass.label, extraElementClass?.label)}>{label}</label>
				{!!secondaryLabel && (
					<label className={clsx(TextAreaElementClass.secondaryLabel, extraElementClass?.secondaryLabel)}>{secondaryLabel}</label>
				)}
			</div>
			<textarea
				ref={ref}
				name={name}
				className={clsx(TextAreaElementClass.textarea, extraElementClass?.textarea)}
				disabled={disabled}
				aria-disabled={disabled}
				onInput={resize}
				onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => {
					if (e.target.value !== value) {
						!!onChange && onChange(e.target.value);
					}
				}}
				onFocus={() => setFocus(true)}
				onBlur={() => setFocus(false)}
				placeholder={placeholder}
				id={inputId}
				aria-describedby={descriptionId}
				{...rest}>
				{value}
			</textarea>
			<div className={clsx(TextAreaElementClass.messageBlock, extraElementClass?.messageBlock)}>
				{!errorMessage ? (
					<div className={clsx(TextAreaElementClass.helperText, extraElementClass?.helperText)}>{helperText}</div>
				) : (
					<div className={clsx(TextAreaElementClass.errorMessage, extraElementClass?.errorMessage)}>{errorMessage}</div>
				)}
			</div>
		</div>
	);
});

.pui-text-area {
  width:100%;
  color: var(--pui-text, #31333e);
  box-sizing: border-box;
  font-size: 1rem;
  * {
    box-sizing: border-box;
  }
  &__label-block {
    font-size: .875rem;
    display: flex;
    justify-content: space-between;
    margin-bottom: .25rem;
  }
  &__label-secondary {
    color: var(--pui-text-secondary, #63636e);
  }
  textarea {
    box-sizing: border-box;
    line-height: 1.375;
    width:100%;
    font-family: inherit;
    color: inherit;
    outline: 0;
    display: block;
    margin:0;
    box-shadow: none;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    &:disabled {
      cursor: not-allowed;
    }
    &::placeholder {
      color: var(--pui-input-placeholder, #adb5bd);
    }
  }
  &__message-block {
    font-size: .75rem;
    margin-top: .25em;
    color: var(--pui-text-secondary, #63636e);
  }

  /* Textfield size styles */
  &--sm {
    .pui-text-area__label-block {
      font-size: .75rem;
    }
    textarea {
      padding:.3125rem .5rem;
      font-size: .875rem;
      min-height: 2rem;
      &:not([rows]) {
        min-height: 3rem;
      }
    }
    .pui-text-area__message-block {
      font-size: .65rem;
    }
    &.pui-text-area--line {
      textarea {
        padding:.125rem 0;
        min-height: 1.625rem;
        &:not([rows]) {
          min-height: 2.45rem;
        }
      }
    }
  }
  &--md {
    textarea {
      padding:.4375rem .75rem;
      min-height: 2.5rem;
      &:not([rows]) {
        min-height: 3.75rem;
      }
    }
    &.pui-text-area--line {
      textarea {
        padding:.125rem 0;
        min-height: 1.875rem;
        &:not([rows]) {
          min-height: 2.8125rem;
        }
      }
    }
  }
  &--lg {
    textarea {
      padding:.625rem 1rem;
      font-size: 1.125rem;
      min-height: 3rem;
      &:not([rows]) {
        min-height: 4.5rem;
      }
    }
    &.pui-text-area--line {
      textarea {
        padding:.125rem 0;
        min-height: 2rem;
        &:not([rows]) {
          min-height: 3rem;
        }
      }
    }
  }

  /* Textfield variant styles */
  &--outlined {
    textarea {
      border: 1px solid var(--pui-soft-border, #dadce3);
      border-radius: 5px;
      overflow: hidden;
      background-color: transparent;
    }
  }
  &--line {
    textarea {
      border:0;
      border-bottom: 1px solid var(--pui-soft-border, #dadce3);
      margin: 0 0 .3rem;
      background-color: transparent;
    }
  }
  &--filled {
    textarea {
      border: 1px solid var(--pui-input-filler, #f0f0f2);
      border-radius: 5px;
      overflow: hidden;
      background-color: var(--pui-input-filler, #f0f0f2);
    }
  }

  /* Textfield dark mode styles */
  .pui-dark-mode & {
    color: var(--pui-text-in-dark, #e7e7e9);
    &__label-secondary {
      color: var(--pui-text-secondary-in-dark, #a4a4ad);
    }
    textarea {
      border-color: var(--pui-soft-border-in-dark, #373a3a);
      &::placeholder {
        color: var(--pui-input-placeholder-dark, #696969);
      }
    }
    .pui-text-area__message-block {
      color: var(--pui-text-secondary-in-dark, #a4a4ad);
    }
    &.pui-text-area--filled {
      textarea {
        border-color: var(--pui-input-filler-dark, #313437);
        background-color: var(--pui-input-filler-dark, #313437);
      }
      &.pui-text-area--error {
        textarea {
          background-color: var(--pui-error-darken, #230b0b);
        }
      }
    }
  }

  /* Textfield state styles */
  &:hover {
    &:not(.pui-text-area--focus, .pui-text-area--error, .pui-text-area--disabled) {
      textarea:hover {
        border-color: var(--pui-border, #c3c7d0);
      }
    }
    .pui-dark-mode &:not(.pui-text-area--focus, .pui-text-area--error, .pui-text-area--disabled){
      textarea:hover {
        border-color: var(--pui-border-in-dark, #43474a);
      }
    }
  }
  &--disabled {
    textarea {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
  &--focus {
    textarea {
      border-color: var(--pui-info, #008DDA);
      box-shadow: 0 0 0 .5px var(--pui-info, #008DDA);
    }
    &.pui-text-area--line {
      textarea {
        box-shadow: none;
        border-bottom-width:1.5px;
      }
    }
  }
  &--error {
    textarea {
      border-color:var(--pui-error, #e74747);
      box-shadow: 0 0 0 .5px var(--pui-error, #e74747);
    }
    &.pui-text-area--line {
      textarea {
        box-shadow: none;
        border-bottom-width:1.5px;
      }
    }
    .pui-text-area__message-block {
      .pui-text-area__error-message {
        color: var(--pui-error, #e74747);
      }
    }
    &.pui-text-area--filled {
      textarea {
        background-color: var(--pui-error-lighten, #fbe3e3);
      }
    }
  }
}

